(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const names={pl:'Polski · Polish',en:'English · English',de:'Deutsch · German',fr:'Français · French',uk:'Українська · Ukrainian',be:'Беларуская · Belarusian',ru:'Русский · Russian',ka:'ქართული · Georgian',hy:'Հայերեն · Armenian',tk:'Türkmençe · Turkmen'};
let data=structuredClone(window.MISSION_CONTENT), tab='posts', selected=0, lang='pl', dirty=false;
try{const draft=JSON.parse(localStorage.getItem('dp-editor-draft'));if(draft?.version===1&&Array.isArray(draft.posts)&&Array.isArray(draft.gallery)&&draft.payments&&draft.social){data=draft;status('Wczytano lokalny szkic.');}}catch{}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function status(s){$('#editor-status').textContent=s;}
function expand(){for(const item of [...data.posts,...data.gallery]){item.translations??={};for(const code of window.MISSION_LANGUAGES){item.translations[code]??={};for(const field of ['title','excerpt','body'])if(item[field+'Key']&&!item.translations[code][field])item.translations[code][field]=window.MISSION_TRANSLATIONS[code][item[field+'Key']]||'';}}}expand();
function optionList(){return Object.entries(names).map(([code,name])=>`<option value="${code}" ${code===lang?'selected':''}>${name}</option>`).join('');}
function field(label,key,value,type='text'){return `<label>${label}<input type="${type}" data-field="${key}" value="${esc(value)}"></label>`;}
function trField(label,key,item,long=false){return `<label>${label}${key==='title'?`<input data-tr="${key}" value="${esc(item.translations?.[lang]?.[key]||'')}">`:`<textarea data-tr="${key}" class="${long?'long':''}">${esc(item.translations?.[lang]?.[key]||'')}</textarea>`}</label>`;}
function commit(){const item=tab==='posts'?data.posts[selected]:data.gallery[selected];if(tab==='payments'){ $$('[data-pay]').forEach(input=>{const [method,key]=input.dataset.pay.split('.');data.payments[method]??={};data.payments[method][key]=input.value.trim();});$$('[data-social]').forEach(input=>data.social[input.dataset.social]=input.value.trim());return;}if(!item)return;$$('[data-field]').forEach(input=>item[input.dataset.field]=input.type==='checkbox'?input.checked:input.value);$$('[data-tr]').forEach(input=>{item.translations??={};item.translations[lang]??={};item.translations[lang][input.dataset.tr]=input.value;});}
function render(){if(tab==='payments'){renderPayments();return;}const items=tab==='posts'?data.posts:data.gallery;selected=Math.max(0,Math.min(selected,items.length-1));const item=items[selected];$('#editor-area').innerHTML=`<div class="editor-layout"><aside class="editor-sidebar">${items.map((x,i)=>`<button class="entry ${i===selected?'active':''}" data-select="${i}">${esc(x.translations?.pl?.title||x.translations?.en?.title||x.id)}</button>`).join('')}<button class="secondary" id="new-item">+ ${tab==='posts'?'Nowy wpis':'Nowe zdjęcie / wideo'}</button></aside>${item?`<section class="editor-form"><h2>${tab==='posts'?'Treść wpisu':'Materiał w galerii'}</h2><div class="editor-grid">${field('Identyfikator (unikalny)','id',item.id)}${tab==='posts'?field('Zdjęcie: ścieżka lub adres HTTPS','image',item.image):`<label>Rodzaj<select data-field="type"><option value="photo" ${item.type==='photo'?'selected':''}>Zdjęcie</option><option value="video" ${item.type==='video'?'selected':''}>Wideo MP4</option></select></label>`}</div>${tab==='gallery'?field('Plik: ścieżka lub adres HTTPS','src',item.src)+field('Autor / źródło','credit',item.credit):field('Data publikacji (opcjonalna)','date',item.date||'','date')}<p class="helper">Pliki lokalne skopiuj do katalogu assets. Przykład: assets/spotkanie.jpg lub assets/film.mp4. Pliki wideo muszą być odtwarzalne bez logowania; wpisz bezpośredni adres MP4.</p><label class="checkbox"><input type="checkbox" data-field="demo" ${item.demo?'checked':''}>Oznacz jako materiał przykładowy</label>${tab==='posts'?`<label class="checkbox"><input type="checkbox" data-field="published" ${item.published!==false?'checked':''}>Pokaż wpis na stronie po publikacji projektu</label>`:''}<label class="language-select">Język treści<select id="edit-language">${optionList()}</select></label><p class="translations-count">Uzupełnij każdy język osobno. Jeśli tłumaczenia brakuje, strona wyświetli wersję angielską lub polską.</p>${trField('Tytuł', 'title',item)}${tab==='posts'?trField('Krótki opis','excerpt',item)+trField('Treść (zwykły tekst, akapity oddziel pustą linią)','body',item,true):''}<button class="remove" id="remove-item">Usuń z tego szkicu</button></section>`:'<p class="empty">Dodaj pierwszy materiał.</p>'}</div>`;$$('[data-select]').forEach(button=>button.addEventListener('click',()=>{commit();selected=Number(button.dataset.select);render();}));$('#new-item').addEventListener('click',()=>{commit();const id='wpis-'+Date.now().toString(36);items.push(tab==='posts'?{id,published:false,demo:false,image:'',translations:{}}:{id,type:'photo',src:'',demo:false,credit:'',translations:{}});selected=items.length-1;dirty=true;render();});$('#edit-language')?.addEventListener('change',e=>{commit();lang=e.target.value;render();});$('#remove-item')?.addEventListener('click',()=>{commit();items.splice(selected,1);dirty=true;render();status('Usunięto z lokalnego szkicu. Opublikowana strona nie została zmieniona.');});$('#editor-area').oninput=()=>dirty=true;}
function renderPayments(){const methods=['blik','paypal','przelewy24','payu','revolut','zrzutka','patronite'];const labels={blik:'BLIK',paypal:'PayPal',przelewy24:'Przelewy24',payu:'PayU',revolut:'Revolut',zrzutka:'Zrzutka',patronite:'Patronite'};const bank=data.payments.bank||{};const input=(label,method,key,value)=>`<label>${label}<input data-pay="${method}.${key}" value="${esc(value)}"></label>`;$('#editor-area').innerHTML=`<section class="editor-form"><h2>Kontakt i publiczne dane do wpłat</h2><p class="helper">Puste pola pozostawiają metodę nieaktywną. Dodawaj wyłącznie własne, sprawdzone linki HTTPS do profilu lub płatności. Ta strona nie tworzy transakcji u operatora; kwotę i walutę darczyńca potwierdza w jego serwisie.</p><div class="editor-grid"><label>Facebook<input data-social="facebook" value="${esc(data.social.facebook)}"></label><label>Instagram<input data-social="instagram" value="${esc(data.social.instagram)}"></label></div><h2>Przelew bankowy</h2><div class="editor-grid">${input('Odbiorca','bank','recipient',bank.recipient)}${input('IBAN (z kodem kraju)','bank','iban',bank.iban)}${input('BIC / SWIFT (opcjonalnie)','bank','bic',bank.bic)}${input('Tytuł przelewu','bank','title',bank.title)}</div>${methods.map(method=>`<div class="payment-editor"><h2>${labels[method]}</h2><div class="editor-grid">${input('Link jednorazowego wsparcia',''+method,'oneTimeUrl',data.payments[method]?.oneTimeUrl||'')}${input('Link regularnego wsparcia (jeśli dostępny)',''+method,'monthlyUrl',data.payments[method]?.monthlyUrl||'')}</div></div>`).join('')}</section>`;$('#editor-area').oninput=()=>dirty=true;}
function validate(){const ids=new Set();for(const item of [...data.posts,...data.gallery]){if(!item.id||ids.has(item.id))throw Error('Każdy wpis i materiał musi mieć inny identyfikator.');ids.add(item.id);}for(const [name,method] of Object.entries(data.payments)){for(const [key,value] of Object.entries(method)){if(key.endsWith('Url')&&value&&!/^https:\/\//i.test(value))throw Error(name+': link płatności musi zaczynać się od https://');}}for(const value of Object.values(data.social)){if(value&&!/^https:\/\//i.test(value))throw Error('Linki społecznościowe muszą zaczynać się od https://');}}
function download(name,body,mime){const url=URL.createObjectURL(new Blob([body],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
$('#save-draft').addEventListener('click',()=>{try{commit();validate();localStorage.setItem('dp-editor-draft',JSON.stringify(data));dirty=false;status('Szkic zapisany w tej przeglądarce. Strona dla odwiedzających nie została jeszcze zmieniona.');}catch(e){status(e.message);}});
$('#export-js').addEventListener('click',()=>{try{commit();validate();download('content.js','/* Public mission content. */\nwindow.MISSION_CONTENT='+JSON.stringify(data,null,2)+';\n','text/javascript;charset=utf-8');dirty=false;status('Pobrano content.js. Zastąp plik w projekcie i opublikuj stronę ponownie.');}catch(e){status(e.message);}});
$('#export-json').addEventListener('click',()=>{commit();download('dobry-poczatek-content.json',JSON.stringify(data,null,2),'application/json');status('Pobrano kopię zapasową treści.');});
$('#import-json').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const next=JSON.parse(await file.text());if(next.version!==1||!Array.isArray(next.posts)||!Array.isArray(next.gallery)||!next.payments||!next.social)throw Error('Nieprawidłowy plik treści.');data=next;expand();selected=0;dirty=true;render();status('Wczytano plik. Zapisz szkic lub pobierz content.js.');}catch(e){status(e.message);}e.target.value='';});
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>{commit();tab=b.dataset.tab;selected=0;$$('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();}));
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});render();
})();
